param([string]$MigrationPath="$PSScriptRoot/../../sql/updates/world/2026_10_27_07_aluneth_pickup_recovery.sql",[switch]$VerifyLive,[switch]$AddressSanitizer)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/aluneth-pickup-data"
function Section([string]$s,[string]$start,[string]$end){$a=$s.IndexOf($start);$b=$s.IndexOf($end,[Math]::Max(0,$a));if($a -lt 0 -or $b -le $a){throw "Native section missing $start"};$s.Substring($a,$b-$a)}
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory $out -RuntimeDirectories $out -Test {
 $migration=Get-Content $MigrationPath -Raw
 $native=Get-Content "$PSScriptRoot/AlunethPickupOriginal.json" -Raw|ConvertFrom-Json
 $filters=[ordered]@{gameobject_template='entry IN(249814,248572,248574,244556,251677)';gameobject_loot_template='Entry IN(249814,248572)';smart_scripts='entryorguid IN(106756,249814,248572,248574) OR(action_type=50 AND action_param1=248574)';conditions='(SourceTypeOrReferenceId=22 AND SourceEntry IN(106756,249814,248572,248574)) OR(SourceTypeOrReferenceId=17 AND SourceEntry IN(211954,208011,218172)) OR(SourceTypeOrReferenceId=4 AND SourceGroup IN(249814,248572))';spell_script_names='ABS(spell_id) IN(211954,208011,218172)';spell_scene='MiscValue IN(1244,1269)';spell_target_position='id=218172';gameobject='id IN(249814,248572,248574)';creature_template='entry=106756';creature='id=106756'}
 $setup='';foreach($t in $filters.Keys){$setup+="CREATE TEMPORARY TABLE saved_$t LIKE $t;INSERT INTO saved_$t SELECT * FROM $t WHERE $($filters[$t]);CREATE TEMPORARY TABLE $t LIKE saved_$t;INSERT INTO $t SELECT * FROM saved_$t;`n"}
 function InsertRows($table,$fields,$rows){$values=@();foreach($row in $rows){$cell=@();foreach($field in $fields){$value=$row.$field;if($value -is [string]){$cell+="'"+$value.Replace("'","''")+"'"}elseif($null -eq $value){$cell+='NULL'}else{$cell+=[Convert]::ToString($value,[Globalization.CultureInfo]::InvariantCulture)}};$values+='('+($cell -join ',')+')'};'INSERT INTO '+$table+'('+($fields -join ',')+') VALUES'+($values -join ',')+';'}
 $setup+="UPDATE gameobject_template SET AIName='SmartGameObjectAI',ScriptName='go_artifact_acquisition' WHERE entry=249814;DELETE FROM smart_scripts WHERE(entryorguid=106756 AND source_type=0) OR(entryorguid=249814 AND source_type=1);DELETE FROM conditions WHERE(SourceTypeOrReferenceId=4 AND SourceGroup=249814) OR(SourceTypeOrReferenceId=17 AND SourceEntry=211954);DELETE FROM spell_script_names WHERE spell_id=211954 AND ScriptName IN('spell_lights_wrath_pickup_cast','spell_lights_wrath_pickup_scene');"+(InsertRows smart_scripts $native.fields $native.rows)
 function Snapshot([string]$label,[switch]$Filtered){($filters.Keys|ForEach-Object {$where=if($Filtered){' WHERE '+$filters[$_]}else{''};"SELECT '$label-$_',a.* FROM $_ a$where;"}) -join "`n"}
 function Rows($rows,[string]$label){@($rows|Where-Object {$_ -like "$label`t*"}|ForEach-Object {$_.Substring($label.Length+1)}|Sort-Object -CaseSensitive)}
 function Signature($rows,[string]$label){(Rows $rows $label) -join "`n"}
 $db=(Get-Content "$repo/build-extractors/bin/Release/worldserver.conf"|Where-Object {$_ -match '^WorldDatabaseInfo\s*='}).Split('"')[1].Split(';')
 function Query([string]$sql,[switch]$Expected){$prior=$env:MYSQL_PWD;try{$env:MYSQL_PWD=$db[3];$rows=@($sql|& C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe --host=$($db[0]) --port=$($db[1]) --user=$($db[2]) --database=$($db[4]) --batch --raw --skip-column-names --force 2> "$out/sql-stderr.txt");$code=$LASTEXITCODE}finally{$env:MYSQL_PWD=$prior};$err=Get-Content "$out/sql-stderr.txt" -Raw;if($Expected){if($err -notmatch '1644 \(45000\)' -or @($err -split "`n"|Where-Object {$_ -match '^ERROR '}).Count -ne 1){throw 'Expected Aluneth refusal missing'}}elseif($code -or $err){throw 'Aluneth TEMP/read-only query failed'};$rows}
 $normalize="UPDATE gameobject_template SET AIName='SmartGameObjectAI',ScriptName='go_artifact_acquisition' WHERE entry=249814;UPDATE smart_scripts SET link=4,action_param3=0 WHERE entryorguid=106756 AND source_type=0 AND id=3;DELETE FROM conditions WHERE(SourceTypeOrReferenceId=4 AND SourceGroup=249814) OR(SourceTypeOrReferenceId=17 AND SourceEntry=211954);DELETE FROM spell_script_names WHERE spell_id=211954 AND ScriptName IN('spell_lights_wrath_pickup_cast','spell_lights_wrath_pickup_scene');"+(InsertRows smart_scripts $native.fields @($native.rows|Where-Object {$_.entryorguid -eq 249814 -or $_.id -eq 4}))
 $predicates="SELECT 'loot',ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition FROM conditions WHERE SourceTypeOrReferenceId=4 AND SourceGroup=249814 ORDER BY ElseGroup,ConditionTypeOrReference;SELECT 'cast',ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition FROM conditions WHERE SourceTypeOrReferenceId=17 AND SourceEntry=211954 ORDER BY ElseGroup,ConditionTypeOrReference;"
 $rows=Query "$setup`n$(Snapshot 'original')`n$migration`n$(Snapshot 'first')`n$migration`n$(Snapshot 'second')`n$predicates`n$normalize`n$(Snapshot 'normalized')"
 foreach($t in $filters.Keys){if((Signature $rows "first-$t") -cne (Signature $rows "second-$t")){throw "Aluneth not idempotent: $t"};if((Signature $rows "original-$t") -cne (Signature $rows "normalized-$t")){throw "Aluneth changed another field/row: $t"}}
 foreach($kind in @('loot','cast')){[IO.File]::WriteAllLines("$out/$kind.tsv",[string[]](Rows $rows $kind));$count=if($kind -eq 'loot'){14}else{28};if((Rows $rows $kind).Count -ne $count){throw 'Aluneth predicate count differs'}}
 $changes=@("UPDATE gameobject_template SET ScriptName='custom' WHERE entry=249814;",'UPDATE gameobject_template SET Data1=0 WHERE entry=249814;','UPDATE gameobject_loot_template SET Item=1 WHERE Entry=249814;','UPDATE smart_scripts SET action_param3=4 WHERE entryorguid=106756 AND source_type=0 AND id=3;','UPDATE smart_scripts SET target_o=0 WHERE entryorguid=106756 AND source_type=0 AND id=4;','UPDATE smart_scripts SET target_x=0 WHERE entryorguid=106756 AND source_type=0 AND id=2;','UPDATE conditions SET ConditionTarget=0 WHERE SourceTypeOrReferenceId=22 AND SourceEntry=106756;',"UPDATE creature SET PhaseId='1' WHERE id=106756;","INSERT INTO spell_script_names VALUES(211954,'custom');",'UPDATE spell_scene SET PlaybackFlags=0 WHERE MiscValue=1269;','UPDATE smart_scripts SET event_param1=1 WHERE entryorguid=249814 AND source_type=1;','DELETE FROM conditions WHERE SourceTypeOrReferenceId=22 AND SourceEntry=106756 AND SourceGroup=1;',"INSERT INTO smart_scripts(entryorguid,source_type,id,event_type,action_type,action_param1,comment) VALUES(999999,0,0,61,50,248574,'custom producer');","INSERT INTO conditions(SourceTypeOrReferenceId,SourceGroup,SourceEntry,ConditionTypeOrReference,ConditionValue1,Comment) VALUES(4,249814,127857,15,1,'custom');")
 foreach($change in $changes){$r=Query "$setup`n$change`n$(Snapshot 'before')`n$migration`n$(Snapshot 'after')" -Expected;foreach($t in $filters.Keys){if((Signature $r "before-$t") -cne (Signature $r "after-$t")){throw "Refused Aluneth changed $t"}}}
 # The already-applied branch must also refuse altered same-count data.
 foreach($change in @('UPDATE conditions SET ConditionValue1=1 WHERE SourceTypeOrReferenceId=17 AND SourceEntry=211954 AND ElseGroup=0 AND ConditionTypeOrReference=15;','UPDATE smart_scripts SET link=0 WHERE entryorguid=106756 AND source_type=0 AND id=3;')){
  $r=Query "$setup`n$migration`n$change`n$(Snapshot 'before')`n$migration`n$(Snapshot 'after')" -Expected
  foreach($t in $filters.Keys){if((Signature $r "before-$t") -cne (Signature $r "after-$t")){throw "Refused applied Aluneth changed $t"}}
 }
 if($VerifyLive){
  $sha=[Security.Cryptography.SHA1]::Create();try{$hash=[BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(([IO.File]::ReadAllText((Resolve-Path $MigrationPath))).Replace("`r`n","`n")))).Replace('-','')}finally{$sha.Dispose()}
  $live=Query "SET SESSION TRANSACTION READ ONLY;SELECT 'update',hash,state FROM updates WHERE name='2026_10_27_07_aluneth_pickup_recovery.sql';$(Snapshot 'live' -Filtered)"
  if($live -notcontains "update`t$hash`tRELEASED"){throw 'Live Aluneth updater/hash differs'}
  foreach($t in $filters.Keys){if((Signature $rows "first-$t") -cne (Signature $live "live-$t")){throw "Live Aluneth differs: $t"}}
 }
 $s=Get-Content "$repo/src/server/game/Conditions/ConditionMgr.cpp" -Raw
 $cases=(Section $s '        case CONDITION_ITEM:' '        case CONDITION_ITEM_EQUIPPED:')+(Section $s '        case CONDITION_CLASS:' '        case CONDITION_RACE:')+(Section $s '        case CONDITION_QUESTREWARDED:' '        case CONDITION_QUEST_NONE:')+(Section $s '        case CONDITION_MAPID:' '        case CONDITION_AREAID:')+(Section $s '        case CONDITION_SCENARION_STEP:' '        case CONDITION_REALM_ACHIEVEMENT:')+(Section $s '        case CONDITION_ALIVE:' '        case CONDITION_HP_VAL:')
 [IO.File]::WriteAllText("$out/Conditions.inc",$cases)
 [IO.File]::WriteAllText("$out/ElseGroups.inc",(Section $s 'bool ConditionMgr::IsObjectMeetToConditionList(' 'bool ConditionMgr::IsObjectMeetToConditions(WorldObject* object,'))
 $s=Get-Content "$repo/src/server/game/Loot/LootMgr.cpp" -Raw
 [IO.File]::WriteAllText("$out/LootCondition.inc",(Section $s 'bool LootItem::AllowedForPlayer(Player const* player) const' 'void LootItem::AddAllowedLooter('))
 $recheck=Section $s '    if (item && !AllowedForPlayer(player,' 'uint32 Loot::GetMaxSlotInLootFor('
 [IO.File]::WriteAllText("$out/SlotRecheck.inc",$recheck.Substring(0,$recheck.LastIndexOf('}')))
 $s=Get-Content "$repo/src/server/game/Entities/GameObject/GameObjectData.cpp" -Raw
 [IO.File]::WriteAllText("$out/GetLootId.inc",(Section $s 'uint32 GameObjectTemplate::GetLootId() const' 'uint32 GameObjectTemplate::GetGossipMenuId() const'))
 $vs=& "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe" -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
 $asan=if($AddressSanitizer){'/fsanitize=address /Zi'}else{''}
 [IO.File]::WriteAllText("$out/run.cmd","@echo off`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`ncd /d `"$out`"`ncl /nologo /EHsc /std:c++17 /W4 $asan /I`"$out`" `"$PSScriptRoot/AlunethConditionsTest.cpp`" /Fe:test.exe /Fo:test.obj`nif errorlevel 1 exit /b 1`ntest.exe loot.tsv cast.tsv`nexit /b %errorlevel%`n")
 & "$out/run.cmd";if($LASTEXITCODE){throw 'Native conditions regression failed'}
 'PASS ten complete TEMP tables, repeated migration/exact normalization/sixteen old/applied custom refusals; only Mage source3 link/creator flag, premature portal/root row and42 new predicates/two bindings change. Priest/shared sources/scene/target/loot preserved; native cached-slot and cast checks pass. No character mutation.'
